// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"all-time-high":{"slug":"all-time-high","cat":"basics","en":"All-time high (ATH)","contentLocale":"en","term":"All-time high (ATH)","aka":["ATH","all time high","record high"],"short":"An all-time high (ATH) is the highest price an asset has ever reached in its trading history, and the opposite, the lowest price ever, is called an all-time low (ATL).","body":["Data sites and exchanges show how far a coin is from its ATH, for example \"down 65 percent from ATH\". This gives context: a coin that has fallen far from its peak may still be in recovery, while a coin breaking a new ATH has no historic sellers waiting at higher prices.","ATH figures can differ between sources. One exchange may record a brief spike to a price that others never traded, and some sites use closing prices while others use intraday highs. Check which data you are looking at.",["New all-time highs often attract attention and ",["FOMO","fomo"],". Breaking an ATH can lead to further gains, but it can also mark a local top if buyers become exhausted. Distance from ATH is a description of the past, not a target, and a coin below its old high is not guaranteed to return there."]],"example":["Suppose a coin's ATH is 12 ",["USDT","usdt"]," and it now trades at 3 USDT, down 75 percent. Many beginners think it only needs to rise 75 percent to get back, but it actually needs to quadruple, a 300 percent gain, to reach 12 again. If it rose 75 percent from 3, it would only be at 5.25 USDT, still 56 percent below the ATH."],"mistakes":["Buying a coin only because it is far below its ATH and assuming it must return.","Miscalculating the recovery needed after a large percentage drop.","Chasing a breakout to a new ATH with high leverage."],"faq":[{"q":"What does ATH mean in crypto?","a":"ATH means all-time high, the highest price an asset has ever traded at."},{"q":"What is ATL?","a":"ATL means all-time low, the lowest price an asset has ever traded at."},{"q":"Why do different sites show different ATHs?","a":"They use different exchanges, price feeds and methods, such as intraday highs versus daily closes."}],"title":"What is an all-time high (ATH) in crypto? Meaning","description":"Learn what ATH and ATL mean, how to read distance from all-time high and why recovery needs larger gains than drops.","related":[["bull-market","Bull market","A bull market is a sustained period when prices rise broadly and investor confidence is high, commonly described as a gain of 20 percent or more from a recent low."],["fomo","FOMO","FOMO, or fear of missing out, is the anxious urge to buy an asset after its price has already risen sharply, driven by the worry that others are profiting without you."],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings."],["support-and-resistance","Support and resistance","Support and resistance are price zones where an asset has repeatedly stopped falling (support) or stopped rising (resistance), because buying or selling interest tends to cluster there."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"coin-margined-futures":{"slug":"coin-margined-futures","cat":"derivatives","en":"Coin-margined (inverse) futures","contentLocale":"en","term":"Coin-margined (inverse) futures","aka":["inverse futures","coin-margined contracts","COIN-M"],"short":"Coin-margined (inverse) futures are futures contracts where margin and profit or loss are in the underlying coin, such as BTC, instead of a stablecoin.","body":[["In a coin-margined ",["BTC","bitcoin"]," ",["contract","smart-contract"]," you deposit BTC as margin, and gains and losses are paid in BTC. Contracts are often quoted in USD value, for example 100 USD per contract, which is why they are called inverse: your profit in BTC follows the formula position value × (1 ÷ entry price − 1 ÷ exit price)."],"This structure suits holders who already have the coin and want to measure results in it. Miners and long-term holders use coin-margined shorts to hedge, because the BTC they post as margin rises in value as the short loses, and falls as the short gains.",["The catch is double exposure on longs. If you go long with BTC as margin, both your position and your collateral lose value when the price falls, so ",["liquidation","liquidation"]," can come faster than you expect. Profit and loss are also not linear in USD terms. Contract sizes and available coins differ by exchange."]],"example":"Suppose you open a 10,000 USD long on a BTC inverse contract at 50,000 USD. If BTC rises to 60,000, your profit is 10,000 × (1 ÷ 50,000 − 1 ÷ 60,000) ≈ 0.0333 BTC, worth about 2,000 USD at the new price. If BTC instead falls to 40,000, your loss is 10,000 × (1 ÷ 40,000 − 1 ÷ 50,000) = 0.05 BTC, and the BTC you posted as margin has also lost 20% of its USD value.","mistakes":["Opening a leveraged long with coin margin without realising the collateral falls along with the position.","Expecting profit and loss to be linear in USD as it is with USDT contracts.","Confusing contract count with coin amount when sizing the position."],"faq":[{"q":"Why are coin-margined futures called inverse?","a":"Because profit and loss in the coin are calculated from the inverse of the price. That makes payoffs non-linear when measured in the coin."},{"q":"Who should use coin-margined futures?","a":"They suit people who hold the coin and think in coin terms, such as miners hedging output. Many beginners find USDT-margined contracts easier to understand."}],"title":"What are coin-margined (inverse) futures? Explained","description":"Learn how coin-margined inverse futures work, how profit is calculated in BTC and why longs carry double exposure.","related":[["usdt-margined-futures","USDT-margined (linear) futures","USDT-margined (linear) futures are futures contracts where margin, profit and loss are all in the stablecoin USDT, so results move in a straight line with the price."],["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["unrealized-pnl","Unrealized PnL","Unrealized PnL is the profit or loss on a position that is still open, calculated from your entry price and the current price, and it only becomes real when you close the position."],["hedging","Hedging","Hedging is opening a position that offsets the risk of another position, so that a loss on one is partly or fully balanced by a gain on the other."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: you're not buying the same thing"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"hedging":{"slug":"hedging","cat":"derivatives","en":"Hedging","contentLocale":"en","term":"Hedging","aka":["hedge","hedging strategy"],"short":"Hedging is opening a position that offsets the risk of another position, so that a loss on one is partly or fully balanced by a gain on the other.","body":[["The classic crypto hedge is holding a coin and ",["shorting","short-selling"]," the same coin with futures. If the price falls, the spot holding loses value and the short gains. You keep ownership of your coins, for example for ",["staking","staking"],", tax timing or long-term plans, while reducing exposure to a drop."],["A hedge can be full or partial. Shorting the same amount you hold makes you roughly market-neutral; shorting half cuts your exposure in half. Options are another tool: buying a ",["put option","options"]," limits losses below a set price in exchange for paying a premium up front."],["Hedging is not free. Futures hedges have fees and funding, which can be a cost or an income. Options cost a premium. A hedge also caps your upside, and an imperfect hedge, such as shorting ",["BTC","bitcoin"]," to protect a small ",["altcoin","altcoin"],", can fail when the two do not move together. Margin on the hedge must be managed too, or it can be liquidated during a rally while your spot gains."]],"example":["Suppose you hold 10 ",["ETH","ethereum"]," at 3,000 USDT, worth 30,000 USDT. You short 10 ETH on a perpetual at 3,000 using 3,000 USDT of margin. ETH falls to 2,400: your spot loses 6,000 USDT and the short gains 6,000 USDT, so your total stays near 30,000 before fees and funding. If ETH rises to 3,600 instead, spot gains 6,000 and the short loses 6,000, so you miss the upside."],"mistakes":["Hedging with high leverage so the short gets liquidated in a rally while the spot gains are not available as margin.","Forgetting funding costs on a long-running perpetual hedge.","Hedging an altcoin with a BTC short and assuming the two will always move together."],"faq":[{"q":"How do you hedge crypto holdings?","a":"The most common ways are shorting the same coin with futures or buying put options. Each reduces downside but has costs and caps or changes your upside."},{"q":"Is hedging the same as closing the position?","a":"The economic exposure is similar, but you keep the coins. That can matter for staking, tax timing or simply wanting to keep the asset."}],"title":"What is hedging in crypto? How to protect a position","description":"Learn how hedging works in crypto with futures or options, what a full or partial hedge does, and its costs.","related":[["short-selling","Short selling","Short selling is a way to profit from a falling price by selling an asset you have borrowed, or opening a short contract, and buying it back later at a lower price."],["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["options","Crypto options","Crypto options are contracts that give the buyer the right, but not the obligation, to buy (call) or sell (put) a cryptocurrency at a set strike price on or before a set expiry date."],["portfolio-margin","Portfolio margin","Portfolio margin is a margin system that sets your collateral requirement based on the combined risk of all your positions, so hedged positions need less margin than they would separately."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futures: you're not buying the same thing"},"coin":null,"tool":null,"cta":false},"options":{"slug":"options","cat":"derivatives","en":"Crypto options","contentLocale":"en","term":"Crypto options","aka":["options","call option","put option"],"short":"Crypto options are contracts that give the buyer the right, but not the obligation, to buy (call) or sell (put) a cryptocurrency at a set strike price on or before a set expiry date.","body":["The buyer pays a premium up front. A call option gains value when the price rises above the strike; a put gains when the price falls below it. If the option expires without value, the buyer loses only the premium. The seller, also called the writer, receives the premium but takes on the obligation and can face large losses.",["Option prices depend on the current price, the strike, time to expiry and implied ",["volatility","volatility"],", the market's estimate of how much the price may move. Crypto volatility is high, so premiums are often expensive compared with stock options. Most crypto options are European style, exercisable only at expiry, and settle in cash."],["Traders use options to hedge, for example buying puts to protect holdings, or to bet on direction with a capped loss. Deribit is a major crypto options venue, and exchanges such as OKX, Binance and Bybit also list options. Products like ",["dual investment","dual-investment"]," are built on selling options. ",["Contract","smart-contract"]," sizes and settlement rules differ by venue."]],"example":["Suppose ",["BTC","bitcoin"]," trades at 65,000 ",["USDT","usdt"]," and you buy a call for 0.1 BTC with a strike of 70,000, expiring in a month, for a premium of 200 USDT. If BTC ends at 76,000, the call pays 0.1 × 6,000 = 600 USDT, a net gain of 400 USDT. If BTC ends below 70,000, the option expires worthless and you lose the 200 USDT. Your break-even price is 72,000."],"mistakes":["Selling options for the premium without understanding the size of the potential loss.","Buying options that are far from the money and short-dated, where most expire worthless.","Ignoring implied volatility, which can make an option lose value even when price moves your way."],"faq":[{"q":"What is the difference between options and futures?","a":"Futures oblige both sides to settle and can be liquidated. An option buyer has a right, not an obligation, and can lose at most the premium."},{"q":"What happens when a crypto option expires?","a":"If it is in the money, it usually settles automatically in cash. If not, it expires worthless and the buyer loses the premium."}],"title":"What are crypto options? Calls and puts explained","description":"Learn how crypto options work, the difference between calls and puts, premiums, strike prices and how buyers and sellers profit.","related":[["futures-contract","Futures contract","A futures contract is an agreement to buy or sell an asset at a set price in the future, which lets you trade price moves with margin and leverage without holding the asset itself."],["hedging","Hedging","Hedging is opening a position that offsets the risk of another position, so that a loss on one is partly or fully balanced by a gain on the other."],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings."],["dual-investment","Dual investment","Dual investment is a structured exchange product where you earn a fixed yield but may be paid back in a different coin depending on whether the price ends above or below a target price on settlement."]],"lesson":null,"coin":null,"tool":"/topics/derivatives","cta":false},"custodial-wallet":{"slug":"custodial-wallet","cat":"wallets-security","en":"Custodial wallet","contentLocale":"en","term":"Custodial wallet","aka":["hosted wallet","exchange wallet","custodial account"],"short":"A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf.","body":["When you deposit coins to an exchange, they go into wallets the exchange controls. Your account shows a balance, but the exchange holds the keys. You can trade, withdraw or transfer, as long as the company processes your request.",["The benefits are convenience and support. There is no ",["seed phrase","seed-phrase"]," to lose, you can reset a forgotten password, and trading is instant. Regulated custodians must meet rules on security, segregation of client assets and identity checks, which vary by country."],["The main risk is counterparty risk. If the company is hacked, freezes withdrawals, becomes insolvent or blocks your account, you may not get your funds back quickly or at all. Check how an exchange protects client assets, whether it publishes ",["proof of reserves","proof-of-reserves"],", and enable ",["two-factor authentication","two-factor-authentication"]," and withdrawal address whitelisting. Many users keep only trading funds on exchanges and move long-term holdings to self-custody."]],"example":["Suppose you hold 4,000 ",["USDT","usdt"]," and 1 ",["ETH","ethereum"]," on an exchange. You lose your phone and two-factor app, so you complete an identity check and support restores access within a few days. That recovery would be impossible with a lost seed phrase. However, if the same exchange paused withdrawals during a crisis, your 4,000 USDT and 1 ETH would be stuck until it resumed, because you never held the keys."],"mistakes":["Keeping all long-term holdings on an exchange without considering counterparty risk.","Not enabling two-factor authentication and withdrawal whitelists on a custodial account.","Assuming funds in a custodial wallet are protected like a bank deposit in every country."],"faq":[{"q":"What is the difference between custodial and non-custodial wallets?","a":"In a custodial wallet a company holds the private keys. In a non-custodial wallet you hold them yourself, usually via a seed phrase."},{"q":"Is a custodial wallet safe?","a":"It can be convenient and well secured, but you depend on the company's security and solvency. Proof of reserves and strong account security reduce, but do not remove, that risk."}],"title":"What is a custodial wallet? Pros, cons and risks","description":"Learn what a custodial wallet is, how exchanges hold your keys, and the convenience and counterparty risk it brings.","related":[["non-custodial-wallet","Non-custodial wallet (self-custody wallet)","A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you."],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."],["proof-of-reserves","Proof of reserves","Proof of reserves is a report in which a crypto exchange shows that the assets it holds in wallets it controls are at least equal to the balances it owes its customers."],["crypto-wallet","Crypto wallet","A crypto wallet is software or a device that stores the private keys controlling your cryptocurrency and lets you send, receive and manage it on the blockchain."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Where are my coins? Exchange vs wallet"},"coin":null,"tool":null,"cta":false},"on-chain-analysis":{"slug":"on-chain-analysis","cat":"onchain","en":"On-chain analysis","contentLocale":"en","term":"On-chain analysis","aka":["on-chain data","onchain analysis","on-chain metrics"],"short":"On-chain analysis is the study of public blockchain data, such as transactions, wallet balances and exchange flows, to understand how a network is used and how holders behave.","body":[["Every transaction on a public ",["blockchain","blockchain"]," like ",["Bitcoin","bitcoin"]," or ",["Ethereum","ethereum"]," is recorded and visible. On-chain analysts group this raw data into metrics: ",["active addresses","active-addresses"],", transaction counts, ",["exchange inflows and outflows","exchange-netflow"],", ",["whale","whale"]," holdings, coin age, fees and more. Unlike price charts, these numbers show what holders actually do with their coins."],"Traders use on-chain data as context. Large deposits to exchanges can hint at selling pressure, while coins leaving exchanges for self-custody may suggest long-term holding. Long-term investors look at network usage and fee revenue to judge whether a chain is growing.","The limits are important. Addresses are pseudonymous, so labels such as exchange wallet or whale come from analytics providers and can be wrong. One person can control many addresses, and one exchange address can hold funds for millions of users. Off-chain activity, such as trading inside an exchange, does not appear at all. On-chain signals work best combined with price, derivatives and news data, not as standalone buy or sell triggers."],"example":"Suppose an analytics dashboard shows that 25,000 BTC moved onto exchanges in one day, compared with a 30-day average of 10,000 BTC. That is 2.5 times the usual inflow. You check further and find that 15,000 BTC came from a single labelled address belonging to an exchange moving funds between its own wallets. The real unusual inflow is closer to 10,000 BTC, roughly normal, so the alarming headline number tells you little on its own.","mistakes":["Treating one on-chain metric as a precise trading signal without checking context.","Trusting address labels blindly when internal exchange transfers can distort flow data.","Comparing metrics across chains without adjusting for different fee levels and address usage patterns."],"faq":[{"q":"Does on-chain analysis predict price?","a":"It does not predict price on its own. It shows how coins move and how networks are used, which can add context to price and sentiment analysis."},{"q":"What are common on-chain metrics?","a":"Popular metrics include active addresses, exchange netflow, whale balances, transaction fees, hash rate for proof-of-work chains, and stablecoin supply on exchanges."}],"title":"What is on-chain analysis? Meaning and key metrics","description":"Learn what on-chain analysis is, which blockchain metrics traders watch, and the limits of reading wallet and exchange flow data.","related":[["exchange-netflow","Exchange inflows and outflows","Exchange inflows and outflows measure how much of a coin moves onto and off centralized exchanges, and netflow is inflows minus outflows over a period."],["whale","Whale","A whale is an individual or entity that holds or trades such a large amount of a cryptocurrency that their moves can noticeably affect its price or liquidity."],["active-addresses","Active addresses","Active addresses are the number of unique blockchain addresses that sent or received a transaction during a given period, often counted per day."],["block-explorer","Block explorer","A block explorer is a website or app that lets you search a blockchain's public records, including transactions, addresses, blocks and token transfers."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"grid-trading-bot":{"slug":"grid-trading-bot","cat":"exchange-features","en":"Grid trading bot","contentLocale":"en","term":"Grid trading bot","aka":["grid bot","spot grid","futures grid"],"short":"A grid trading bot is an automated tool that places a ladder of buy and sell limit orders within a price range, profiting from repeated moves up and down.","body":["You choose an upper price, a lower price and the number of grids. The bot splits the range into levels and places buy orders below the current price and sell orders above it. Each time the price drops to a level, it buys; each time it rises to the next level, it sells that slice for a small profit.",["Grid bots work best in sideways, volatile markets. In a strong trend, they struggle: if the price climbs above the range, the bot has sold everything and sits in ",["stablecoins","stablecoin"],"; if it falls below, it holds coins bought at higher prices and shows an unrealised loss. Futures grid bots add ",["leverage","leverage"]," and ",["liquidation","liquidation"]," risk."],["Most major exchanges offer spot and futures grids with suggested settings, often based on recent ",["volatility","volatility"],". Before starting, check the fee per trade, because grids trade often and small profits per grid can be eaten by fees. More grids means more trades with smaller profits each."]],"example":["Suppose ",["ETH","ethereum"]," trades at 3,000 ",["USDT","usdt"]," and you set a spot grid from 2,700 to 3,300 with 6 grids, so the levels are 100 USDT apart. Each grid trades 0.1 ETH. If the price dips to 2,900 and returns to 3,000, the bot buys 0.1 ETH at 2,900 and sells at 3,000, making 10 USDT before fees. With a 0.1% fee per side, fees are about 0.29 plus 0.30, leaving roughly 9.41 USDT. Twenty such round trips in a month would earn about 188 USDT."],"mistakes":["Setting a narrow range in a trending market so the price quickly leaves the grid.","Using too many grids so each profit is smaller than the trading fees.","Running a leveraged futures grid without checking the liquidation price."],"faq":[{"q":"Do grid trading bots make money?","a":"They can profit in ranging markets with enough volatility. In strong trends, especially downtrends, a grid can show losses or sit idle outside its range."},{"q":"What is the difference between spot grid and futures grid?","a":"A spot grid buys and sells real coins with no leverage. A futures grid trades contracts, can go long or short and can use leverage, which adds liquidation risk."}],"title":"What is a grid trading bot? How grid bots work","description":"How a grid trading bot places buy and sell orders in a price range, when grids work best and how fees and trends affect results.","related":[["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) is a strategy of buying a fixed amount of an asset at regular intervals, regardless of price, to spread your entry over time."],["copy-trading","Copy trading","Copy trading is an exchange feature that automatically mirrors another trader's positions in your own account, in proportion to the amount you allocate."],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings."],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."]],"lesson":null,"coin":null,"tool":null,"cta":true}});
